package de.corporate.lc.user.service;
import de.corporate.lc.user.api.*;import de.corporate.lc.user.domain.*;import de.corporate.lc.user.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class RoleService {private final AppRoleRepository roles;private final AppUserRepository users;private final TenantAdministrationLock administration;private final de.corporate.lc.tenant.repository.TenantMembershipRepository memberships;public RoleService(AppRoleRepository roles,AppUserRepository users,TenantAdministrationLock administration){this.roles=roles;this.users=users;this.administration=administration;this.memberships=null;}@org.springframework.beans.factory.annotation.Autowired public RoleService(AppRoleRepository roles,AppUserRepository users,TenantAdministrationLock administration,de.corporate.lc.tenant.repository.TenantMembershipRepository memberships){this.roles=roles;this.users=users;this.administration=administration;this.memberships=memberships;}@Transactional(propagation=org.springframework.transaction.annotation.Propagation.MANDATORY) public RoleView getForAdministration(UUID id){administration.acquire();return RoleView.of(one(id));}public List<RoleView> all(){return roles.findAllByOrderByNameAsc().stream().map(RoleView::of).toList();}public List<PermissionView> permissions(){return Arrays.stream(UserPermission.values()).map(p->new PermissionView(p,p.getLabel())).toList();}
 @Transactional public RoleView create(RoleRequest request){administration.acquire();if(roles.existsByNameIgnoreCase(request.name().trim()))throw new IllegalArgumentException("Rollenname existiert bereits.");AppRole role=new AppRole();role.setName(request.name().trim());role.setBaseRole(request.baseRole());role.setPermissions(new LinkedHashSet<>(request.permissions()));return RoleView.of(roles.save(role));}
 @Transactional public RoleView update(UUID id,RoleRequest request){administration.acquire();AppRole role=one(id);if(roles.findAllByOrderByNameAsc().stream().anyMatch(other->!other.getId().equals(id)&&other.getName().equalsIgnoreCase(request.name().trim())))throw new IllegalArgumentException("Rollenname existiert bereits.");if(role.isSystemRole()&&role.getBaseRole()!=request.baseRole())throw new IllegalArgumentException("Der Basistyp einer Systemrolle kann nicht geändert werden.");if(role.isSystemRole()&&role.getBaseRole()==UserRole.ADMIN&&!request.permissions().contains(UserPermission.USER_MANAGE))throw new IllegalArgumentException("Die Administratorrolle muss Benutzer verwalten dürfen.");if(role.getBaseRole()==UserRole.ADMIN&&request.baseRole()!=UserRole.ADMIN){long affected=home()?users.countByAssignedRoleIdAndActiveTrue(id):memberships.countAccessibleAssignedToRole(id);if(affected>0&&(home()?users.countByRoleAndActiveTrue(UserRole.ADMIN):memberships.countAccessibleAdministrators())<=affected)throw new IllegalArgumentException("Der letzte aktive Administrator kann nicht über seine Rolle herabgestuft werden.");}if(role.getPermissions().contains(UserPermission.USER_MANAGE)&&!request.permissions().contains(UserPermission.USER_MANAGE)&&(home()?users.countByAssignedRoleId(id):memberships.countAssignedToRole(id))>0)throw new IllegalArgumentException("An assigned administration role must retain user-management permission.");role.setName(request.name().trim());role.setBaseRole(request.baseRole());role.setPermissions(new LinkedHashSet<>(request.permissions()));return RoleView.of(role);}
 @Transactional public void delete(UUID id){administration.acquire();AppRole role=one(id);if(role.isSystemRole())throw new IllegalArgumentException("Vordefinierte Rollen können nicht gelöscht werden.");if((home()?users.countByAssignedRoleId(id):memberships.countAssignedToRole(id))>0)throw new IllegalArgumentException("Die Rolle ist noch Benutzern zugewiesen.");roles.delete(role);}private boolean home(){return de.corporate.lc.tenant.domain.Tenant.DEFAULT_ID.equals(de.corporate.lc.tenant.domain.TenantContext.currentId());}private AppRole one(UUID id){return roles.findById(id).orElseThrow(()->new NoSuchElementException("Rolle nicht gefunden"));}}
